export function resolveOrderSource(orderOrSource: any): {
  channel: string;
  label: string;
  subLabel?: string;
  isPaid: boolean;
  color: string;
  bg: string;
  border: string;
  iconType: 'facebook' | 'tiktok' | 'google' | 'instagram' | 'chatgpt' | 'claude' | 'perplexity' | 'copilot' | 'gemini' | 'youtube' | 'yahoo' | 'whatsapp' | 'phone' | 'direct';
} {
  let src = '';
  let landing = '';
  let attr: any = null;

  if (typeof orderOrSource === 'string') {
    src = orderOrSource;
  } else if (orderOrSource && typeof orderOrSource === 'object') {
    src = orderOrSource.source || '';
    landing = orderOrSource.landing || '';
    attr = orderOrSource.attribution || null;
  }

  const s = (src || '').toLowerCase();
  const ch = (attr?.channel || '').toLowerCase();
  const med = (attr?.medium || '').toLowerCase();
  const ref = (attr?.referrer || '').toLowerCase();

  // 0. Explicit Direct / Organic
  if ((ch === 'direct' || s === 'direct') && !attr?.clickId && !ref.includes('facebook') && !ref.includes('google') && !ref.includes('tiktok')) {
    return {
      channel: 'direct',
      label: 'Direct',
      subLabel: landing ? `l/${landing}` : undefined,
      isPaid: false,
      color: '#94a3b8',
      bg: 'rgba(148, 163, 184, 0.12)',
      border: 'rgba(148, 163, 184, 0.25)',
      iconType: 'direct',
    };
  }

  // 1. WhatsApp
  if (ch === 'whatsapp' || s.includes('whatsapp') || s === 'wa') {
    return {
      channel: 'whatsapp',
      label: 'WhatsApp',
      isPaid: false,
      color: '#4ade80',
      bg: 'rgba(37, 211, 102, 0.15)',
      border: 'rgba(37, 211, 102, 0.35)',
      iconType: 'whatsapp',
    };
  }

  // 2. Phone Call
  if (ch === 'phone' || s === 'phone' || s === 'phone_call' || s === 'manual_call') {
    return {
      channel: 'phone',
      label: 'Phone Call',
      isPaid: false,
      color: '#fbbf24',
      bg: 'rgba(245, 158, 11, 0.15)',
      border: 'rgba(245, 158, 11, 0.35)',
      iconType: 'phone',
    };
  }

  // 2b. AI Voice Call (Saika Call Center / Voice Order)
  if (ch === 'ai_voice_call' || s === 'ai_voice_call' || s.includes('voice_call') || s.includes('saika_call') || s.includes('ai_call')) {
    return {
      channel: 'phone',
      label: 'AI Voice Call',
      subLabel: landing ? `l/${landing}` : undefined,
      isPaid: false,
      color: '#38bdf8',
      bg: 'rgba(56, 189, 248, 0.15)',
      border: 'rgba(56, 189, 248, 0.35)',
      iconType: 'phone',
    };
  }

  // 3. Facebook / Meta Ads
  if (ch === 'facebook' || s.includes('facebook') || s === 'fb' || ref.includes('facebook') || s.includes('eventsmanager.facebook')) {
    const isPaid = med === 'cpc' || med.includes('ad') || attr?.clickId || !s.includes('referral');
    return {
      channel: 'facebook',
      label: isPaid ? 'Facebook Ads' : 'Facebook',
      subLabel: landing ? `l/${landing}` : undefined,
      isPaid,
      color: '#60a5fa',
      bg: 'rgba(24, 119, 242, 0.16)',
      border: 'rgba(24, 119, 242, 0.4)',
      iconType: 'facebook',
    };
  }

  // 4. TikTok
  if (ch === 'tiktok' || s.includes('tiktok') || s === 'tt' || ref.includes('tiktok')) {
    const isPaid = med === 'cpc' || med.includes('video') || med.includes('ad') || attr?.clickId;
    return {
      channel: 'tiktok',
      label: isPaid ? 'TikTok Ads' : 'TikTok',
      subLabel: landing ? `l/${landing}` : undefined,
      isPaid,
      color: '#22d3ee',
      bg: 'rgba(0, 242, 254, 0.14)',
      border: 'rgba(0, 242, 254, 0.4)',
      iconType: 'tiktok',
    };
  }

  // 5. Google / Google Ads
  if (ch === 'google' || s.includes('google') || ref.includes('google')) {
    const isPaid = med === 'cpc' || med.includes('ad') || attr?.clickId;
    return {
      channel: 'google',
      label: isPaid ? 'Google Ads' : 'Google Search',
      subLabel: landing ? `l/${landing}` : undefined,
      isPaid,
      color: '#f87171',
      bg: 'rgba(234, 67, 53, 0.14)',
      border: 'rgba(234, 67, 53, 0.35)',
      iconType: 'google',
    };
  }

  // 6. Instagram
  if (ch === 'instagram' || s.includes('instagram') || s === 'ig' || ref.includes('instagram')) {
    return {
      channel: 'instagram',
      label: 'Instagram Ads',
      subLabel: landing ? `l/${landing}` : undefined,
      isPaid: true,
      color: '#f472b6',
      bg: 'rgba(225, 48, 108, 0.16)',
      border: 'rgba(225, 48, 108, 0.4)',
      iconType: 'instagram',
    };
  }

  // 7. Yahoo
  if (ch === 'yahoo' || s.includes('yahoo') || ref.includes('yahoo')) {
    return {
      channel: 'yahoo',
      label: 'Yahoo',
      subLabel: landing ? `l/${landing}` : undefined,
      isPaid: false,
      color: '#c084fc',
      bg: 'rgba(168, 85, 247, 0.16)',
      border: 'rgba(168, 85, 247, 0.4)',
      iconType: 'yahoo',
    };
  }

  // 8. AI Chatbots (ChatGPT, Claude, Perplexity, Copilot, Gemini)
  if (ch === 'chatgpt' || s.includes('chatgpt') || s.includes('openai') || ref.includes('chatgpt') || ref.includes('openai')) {
    return {
      channel: 'chatgpt',
      label: 'ChatGPT (AI)',
      isPaid: false,
      color: '#34d399',
      bg: 'rgba(16, 163, 127, 0.16)',
      border: 'rgba(16, 163, 127, 0.4)',
      iconType: 'chatgpt',
    };
  }
  if (ch === 'claude' || s.includes('claude') || s.includes('anthropic') || ref.includes('claude')) {
    return {
      channel: 'claude',
      label: 'Claude (AI)',
      isPaid: false,
      color: '#fbbf24',
      bg: 'rgba(217, 119, 6, 0.16)',
      border: 'rgba(217, 119, 6, 0.4)',
      iconType: 'claude',
    };
  }
  if (ch === 'perplexity' || s.includes('perplexity') || ref.includes('perplexity')) {
    return {
      channel: 'perplexity',
      label: 'Perplexity (AI)',
      isPaid: false,
      color: '#2dd4bf',
      bg: 'rgba(20, 184, 166, 0.16)',
      border: 'rgba(20, 184, 166, 0.4)',
      iconType: 'perplexity',
    };
  }
  if (ch === 'copilot' || s.includes('copilot') || s.includes('bing') || ref.includes('copilot') || ref.includes('bing')) {
    return {
      channel: 'copilot',
      label: 'Copilot / Bing',
      isPaid: false,
      color: '#38bdf8',
      bg: 'rgba(56, 189, 248, 0.16)',
      border: 'rgba(56, 189, 248, 0.4)',
      iconType: 'copilot',
    };
  }
  if (ch === 'gemini' || s.includes('gemini') || ref.includes('gemini')) {
    return {
      channel: 'gemini',
      label: 'Gemini (AI)',
      isPaid: false,
      color: '#818cf8',
      bg: 'rgba(99, 102, 241, 0.16)',
      border: 'rgba(99, 102, 241, 0.4)',
      iconType: 'gemini',
    };
  }

  // 9. YouTube
  if (ch === 'youtube' || s.includes('youtube') || ref.includes('youtube') || ref.includes('youtu.be')) {
    return {
      channel: 'youtube',
      label: 'YouTube',
      isPaid: false,
      color: '#f87171',
      bg: 'rgba(239, 68, 68, 0.16)',
      border: 'rgba(239, 68, 68, 0.4)',
      iconType: 'youtube',
    };
  }

  // 10. Landing page orders (Historical & Active fallback)
  // When an ad campaign sends users to a landing page, it represents Facebook Ads
  if (s.startsWith('landing_') || s.startsWith('l/') || s.includes('lovelock') || landing) {
    const cleanLanding = (landing || s.replace(/^landing_/, '').replace(/^l\//, '')).trim();
    return {
      channel: 'facebook',
      label: 'Facebook Ads',
      subLabel: cleanLanding ? `l/${cleanLanding}` : undefined,
      isPaid: true,
      color: '#60a5fa',
      bg: 'rgba(24, 119, 242, 0.16)',
      border: 'rgba(24, 119, 242, 0.4)',
      iconType: 'facebook',
    };
  }

  // 11. Direct / Organic / Fallback
  return {
    channel: 'direct',
    label: s && s !== 'direct' ? s : 'Direct / Organic',
    isPaid: false,
    color: '#94a3b8',
    bg: 'rgba(148, 163, 184, 0.12)',
    border: 'rgba(148, 163, 184, 0.25)',
    iconType: 'direct',
  };
}

function originLabel(srcOrOrder: any): string {
  const info = resolveOrderSource(srcOrOrder);
  return info.label;
}

function OriginBadge({ source, order, style }: { source?: string; order?: any; style?: React.CSSProperties }) {
  const info = resolveOrderSource(order || source);

  let iconElem: React.ReactNode = null;
  if (info.iconType === 'facebook') iconElem = <FacebookIcon size={12} />;
  else if (info.iconType === 'tiktok') iconElem = <TikTokIcon size={12} />;
  else if (info.iconType === 'google') iconElem = <GoogleIcon size={12} />;
  else if (info.iconType === 'chatgpt') iconElem = <ChatGPTIcon size={12} />;
  else if (info.iconType === 'instagram') iconElem = <InstagramIcon size={12} />;
  else if (info.iconType === 'whatsapp') iconElem = <WhatsAppIcon size={12} variant="official" />;
  else if (info.iconType === 'phone') iconElem = <span style={{ fontSize: 11 }}>📞</span>;
  else if (info.iconType === 'yahoo') iconElem = <span style={{ fontWeight: 900, color: '#c084fc', fontSize: 10 }}>Y!</span>;
  else if (info.iconType === 'claude' || info.iconType === 'perplexity' || info.iconType === 'copilot') iconElem = <span style={{ fontSize: 11 }}>🤖</span>;
  else if (info.iconType === 'gemini') iconElem = <span style={{ fontSize: 11 }}>✨</span>;
  else if (info.iconType === 'youtube') iconElem = <span style={{ fontSize: 11 }}>▶️</span>;
  else iconElem = <span style={{ fontSize: 11 }}>🌐</span>;

  return (
    <span
      className="origin-chip"
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 5,
        background: info.bg,
        border: `1px solid ${info.border}`,
        color: info.color,
        fontWeight: 600,
        borderRadius: 4,
        ...style,
      }}
      title={`Traffic Source: ${info.label}${info.subLabel ? ` · Landing: ${info.subLabel}` : ''}`}
    >
      {iconElem}
      <span>{info.label}</span>
    </span>
  );
}

function exportCSV(
  orders: any[],
  prodMap?: Record<string, any>,
  landingMap?: Record<string, any>,
  filePrefix = 'timeboost-orders'
) {
  return exportOrdersExcel(orders, prodMap, landingMap, filePrefix);
}

export function getBase64ByteSize(b64: string): number {
  if (!b64) return 0;
  const comma = b64.indexOf(',');
  const raw = comma >= 0 ? b64.slice(comma + 1) : b64;
  return Math.round((raw.length * 3) / 4);
}

export function formatBytes(bytes: number): string {
  if (!bytes || bytes <= 0) return '0 KB';
  if (bytes > 1024 * 1024) return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  return Math.round(bytes / 1024) + ' KB';
}

export async function processImageToWebpOrSvg(file: File): Promise<string> {
  const isSvg = file.type === 'image/svg+xml' || file.name.toLowerCase().endsWith('.svg');
  if (isSvg) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const MAX_BYTES = 100 * 1024; // strictly 100 KB limit
        
        // Progressive reduction steps to guarantee <= 100 KB with highest possible fidelity
        const steps = [
          { maxDim: 1400, quality: 0.82 },
          { maxDim: 1200, quality: 0.78 },
          { maxDim: 1080, quality: 0.72 },
          { maxDim: 960,  quality: 0.65 },
          { maxDim: 850,  quality: 0.58 },
          { maxDim: 750,  quality: 0.50 },
          { maxDim: 650,  quality: 0.42 },
          { maxDim: 550,  quality: 0.35 },
          { maxDim: 450,  quality: 0.30 },
          { maxDim: 360,  quality: 0.25 },
        ];

        let bestResult = '';
        let bestBytes = Infinity;

        for (const step of steps) {
          try {
            let width = img.naturalWidth || img.width;
            let height = img.naturalHeight || img.height;
            if (width > step.maxDim || height > step.maxDim) {
              if (width > height) {
                height = Math.round((height * step.maxDim) / width);
                width = step.maxDim;
              } else {
                width = Math.round((width * step.maxDim) / height);
                height = step.maxDim;
              }
            }
            const canvas = document.createElement('canvas');
            canvas.width = Math.max(1, width);
            canvas.height = Math.max(1, height);
            const ctx = canvas.getContext('2d');
            if (!ctx) continue;
            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = 'high';
            ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

            const webpDataUrl = canvas.toDataURL('image/webp', step.quality);
            const bytes = getBase64ByteSize(webpDataUrl);

            if (bytes < bestBytes) {
              bestBytes = bytes;
              bestResult = webpDataUrl;
            }

            if (bytes <= MAX_BYTES) {
              resolve(webpDataUrl);
              return;
            }
          } catch {
            // continue trying smaller step
          }
        }

        // Return best compressed version
        resolve(bestResult || (e.target?.result as string));
      };
      img.onerror = () => resolve(e.target?.result as string);
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

export async function uploadOptimizedImage(file: File): Promise<{ url: string; deduplicated?: boolean }> {
  const dataUrl = await processImageToWebpOrSvg(file);
  const res = await aFetch('/upload', {
    method: 'POST',
    body: JSON.stringify({ dataUrl })
  });
  const data = await res.json();
  if (!res.ok || !data.url) {
    throw new Error(data.error || 'Upload failed');
  }
  return data;
}

export function MediaPickerModal({
  title = 'Select Photo',
  currentUrl = '',
  extraImages = [],
  onSelect,
  onClose,
}: {
  title?: string;
  currentUrl?: string;
  extraImages?: string[];
  onSelect: (url: string) => void;
  onClose: () => void;
}) {
  const [mediaList, setMediaList] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [selected, setSelected] = useState(currentUrl || '');
  const [uploading, setUploading] = useState(false);
  const [uploadMsg, setUploadMsg] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadMedia = async () => {
    setLoading(true);
    try {
      const res = await aFetch('/admin/media');
      const data = await res.json();
      const serverItems = Array.isArray(data)
        ? data.map((m: any) => ({
            url: m.url || ('/uploads/' + m.name),
            name: m.name || m.url,
            size: m.size || 0,
            modified: m.modified,
          }))
        : [];

      // Combine with extraImages (e.g. current product images)
      const seen = new Set<string>();
      const combined: any[] = [];

      for (const item of serverItems) {
        if (item.url && !seen.has(item.url)) {
          seen.add(item.url);
          combined.push(item);
        }
      }
      for (const url of (extraImages || [])) {
        if (url && !seen.has(url)) {
          seen.add(url);
          combined.unshift({
            url,
            name: url.split('/').pop() || url,
            size: 0,
          });
        }
      }
      setMediaList(combined);
    } catch {
      // fallback
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadMedia();
  }, []);

  const handleUploadFiles = async (files: FileList | File[]) => {
    const list = Array.from(files).filter((f) => f.type.startsWith('image/'));
    if (!list.length) return;
    setUploading(true);
    let lastUrl = '';
    for (let i = 0; i < list.length; i++) {
      const f = list[i];
      setUploadMsg(`⚡ Auto-converting ${f.name} to WebP ≤100KB (${i + 1}/${list.length})...`);
      try {
        const d = await uploadOptimizedImage(f);
        if (d.url) {
          lastUrl = d.url;
          setMediaList((prev) => [
            { url: d.url, name: f.name, size: 0, isNew: true },
            ...prev.filter((x) => x.url !== d.url),
          ]);
        }
      } catch (err: any) {
        alert(err.message || 'Upload failed');
      }
    }
    setUploading(false);
    setUploadMsg('');
    if (lastUrl) {
      setSelected(lastUrl);
    }
  };

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return mediaList;
    return mediaList.filter((m) => (m.name || '').toLowerCase().includes(q) || (m.url || '').toLowerCase().includes(q));
  }, [mediaList, search]);

  return (
    <div
      style={{
        position: 'fixed',
        inset: 0,
        background: 'rgba(5, 4, 12, 0.82)',
        backdropFilter: 'blur(6px)',
        zIndex: 999999,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 16,
      }}
      onClick={onClose}
    >
      <div
        style={{
          width: 'min(940px, 98vw)',
          height: 'min(86vh, 760px)',
          background: '#151226',
          border: '1px solid rgba(139, 92, 246, 0.35)',
          borderRadius: 16,
          display: 'flex',
          flexDirection: 'column',
          boxShadow: '0 25px 60px -15px rgba(0, 0, 0, 0.9)',
          overflow: 'hidden',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div
          style={{
            padding: '16px 20px',
            borderBottom: '1px solid rgba(255, 255, 255, 0.08)',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            background: '#120f20',
          }}
        >
          <div>
            <div style={{ fontSize: 16, fontWeight: 700, color: '#fff', display: 'flex', alignItems: 'center', gap: 8 }}>
              <span>🖼️</span>
              <span>{title}</span>
              <span
                style={{
                  fontSize: 10.5,
                  padding: '2px 8px',
                  borderRadius: 10,
                  background: 'rgba(52, 211, 153, 0.15)',
                  color: '#34d399',
                  border: '1px solid rgba(52, 211, 153, 0.3)',
                  fontWeight: 600,
                }}
              >
                ⚡ Auto WebP / SVG (≤ 100KB)
              </span>
            </div>
            <div style={{ fontSize: 12, color: '#94a3b8', marginTop: 3 }}>
              Select a photo from your media library, or upload a new photo from your computer.
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            style={{ background: 'none', border: 'none', color: '#94a3b8', fontSize: 24, cursor: 'pointer', lineHeight: 1 }}
          >
            ✕
          </button>
        </div>

        {/* Action bar / Search & Computer Upload button */}
        <div
          style={{
            padding: '12px 20px',
            borderBottom: '1px solid rgba(255, 255, 255, 0.06)',
            display: 'flex',
            gap: 12,
            alignItems: 'center',
            background: '#18142b',
            flexWrap: 'wrap',
          }}
        >
          <div style={{ flex: 1, minWidth: 200 }}>
            <input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="🔍 Search photos by name or filename..."
              style={{
                width: '100%',
                padding: '9px 12px',
                background: '#0d0b18',
                border: '1px solid rgba(255, 255, 255, 0.14)',
                borderRadius: 8,
                color: '#fff',
                fontSize: 13,
              }}
            />
          </div>

          <button
            type="button"
            disabled={uploading}
            onClick={() => fileInputRef.current?.click()}
            className="sa-btn primary"
            style={{
              cursor: uploading ? 'wait' : 'pointer',
              whiteSpace: 'nowrap',
              display: 'inline-flex',
              alignItems: 'center',
              gap: 6,
              background: '#7c3aed',
              borderColor: '#7c3aed',
              padding: '9px 16px',
              fontWeight: 700,
            }}
          >
            <span>📁 Upload from Computer</span>
          </button>

          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            multiple
            hidden
            onChange={(e) => {
              if (e.target.files) handleUploadFiles(e.target.files);
              e.target.value = '';
            }}
          />

          <button
            type="button"
            className="sa-btn ghost"
            onClick={loadMedia}
            style={{ padding: '9px 14px' }}
            title="Refresh media list"
          >
            🔄 Refresh
          </button>
        </div>

        {uploading && (
          <div
            style={{
              padding: '10px 20px',
              background: 'linear-gradient(90deg, rgba(124, 58, 237, 0.25), rgba(52, 211, 153, 0.25))',
              borderBottom: '1px solid rgba(124, 58, 237, 0.35)',
              color: '#a7f3d0',
              fontSize: 12.5,
              fontWeight: 600,
              display: 'flex',
              alignItems: 'center',
              gap: 8,
            }}
          >
            <span>⏳</span>
            <span>{uploadMsg || 'Compressing photo to WebP ≤100KB and uploading...'}</span>
          </div>
        )}

        {/* Gallery Grid */}
        <div style={{ flex: 1, overflowY: 'auto', padding: 20 }}>
          {loading ? (
            <div style={{ textAlign: 'center', padding: '60px 0', color: '#94a3b8' }}>
              <div style={{ fontSize: 24, marginBottom: 8 }}>🔄</div>
              <div>Loading media library...</div>
            </div>
          ) : filtered.length === 0 ? (
            <div
              style={{
                textAlign: 'center',
                padding: '50px 20px',
                background: '#120f21',
                borderRadius: 12,
                border: '1px dashed rgba(255, 255, 255, 0.15)',
              }}
            >
              <div style={{ fontSize: 36, marginBottom: 12 }}>🖼️</div>
              <div style={{ fontSize: 15, fontWeight: 700, color: '#fff', marginBottom: 6 }}>
                {search ? 'No matching photos found' : 'No photos found in Media Library'}
              </div>
              <p style={{ fontSize: 13, color: '#94a3b8', maxWidth: 440, margin: '0 auto 18px', lineHeight: 1.5 }}>
                {search
                  ? `No photos matched "${search}". Try another search or upload a photo directly from your device.`
                  : 'You have not uploaded any photos yet. Click below to choose a picture from your computer — it will automatically convert to WebP (≤100KB)!'}
              </p>
              <button
                type="button"
                className="sa-btn primary"
                onClick={() => fileInputRef.current?.click()}
                style={{
                  background: '#7c3aed',
                  borderColor: '#7c3aed',
                  padding: '10px 20px',
                  fontSize: 13,
                  fontWeight: 700,
                  display: 'inline-flex',
                  alignItems: 'center',
                  gap: 8,
                }}
              >
                <span>📁 Upload Photo from Computer</span>
              </button>
            </div>
          ) : (
            <>
              <div style={{ fontSize: 12, color: '#94a3b8', marginBottom: 12, display: 'flex', justifyContent: 'space-between' }}>
                <span>Found <strong>{filtered.length}</strong> photos (Click to select, Double-click to choose instantly):</span>
                {selected && (
                  <span style={{ color: '#34d399', fontWeight: 600 }}>1 photo selected ✓</span>
                )}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(130px, 1fr))', gap: 14 }}>
                {filtered.map((m: any, idx: number) => {
                  const isSelected = selected === m.url;
                  const isWebp = (m.url || '').toLowerCase().endsWith('.webp');
                  const isSvg = (m.url || '').toLowerCase().endsWith('.svg');
                  const extLabel = isWebp ? 'WEBP' : isSvg ? 'SVG' : ((m.url || '').split('.').pop() || '').toUpperCase();

                  return (
                    <div
                      key={m.url || idx}
                      onClick={() => setSelected(m.url)}
                      onDoubleClick={() => {
                        onSelect(m.url);
                        onClose();
                      }}
                      style={{
                        position: 'relative',
                        background: '#0e0c18',
                        borderRadius: 10,
                        overflow: 'hidden',
                        cursor: 'pointer',
                        border: isSelected ? '2.5px solid #10b981' : '1px solid rgba(255, 255, 255, 0.1)',
                        boxShadow: isSelected ? '0 0 16px rgba(16, 185, 129, 0.45)' : 'none',
                        transition: 'all 0.15s ease',
                        display: 'flex',
                        flexDirection: 'column',
                      }}
                      title={`${m.name || m.url}\n(Click to select, Double-click to apply)`}
                    >
                      <div style={{ width: '100%', aspectRatio: '1 / 1', overflow: 'hidden', background: '#080611', position: 'relative' }}>
                        <img
                          src={m.url}
                          alt=""
                          loading="lazy"
                          style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                        />
                        {isSelected && (
                          <div
                            style={{
                              position: 'absolute',
                              top: 6,
                              right: 6,
                              background: '#10b981',
                              color: '#fff',
                              width: 22,
                              height: 22,
                              borderRadius: '50%',
                              display: 'flex',
                              alignItems: 'center',
                              justifyContent: 'center',
                              fontSize: 12,
                              fontWeight: 800,
                              boxShadow: '0 2px 6px rgba(0,0,0,0.6)',
                            }}
                          >
                            ✓
                          </div>
                        )}
                        <div
                          style={{
                            position: 'absolute',
                            bottom: 4,
                            left: 4,
                            background: 'rgba(0,0,0,0.75)',
                            padding: '1px 5px',
                            borderRadius: 4,
                            fontSize: 9,
                            fontWeight: 700,
                            color: isWebp || isSvg ? '#34d399' : '#cbd5e1',
                          }}
                        >
                          {extLabel}
                        </div>
                      </div>

                      <div style={{ padding: '6px 8px', fontSize: 11, background: '#120f21' }}>
                        <div
                          style={{
                            color: '#fff',
                            fontWeight: 600,
                            overflow: 'hidden',
                            textOverflow: 'ellipsis',
                            whiteSpace: 'nowrap',
                          }}
                        >
                          {m.name || m.url.split('/').pop()}
                        </div>
                        {m.size ? (
                          <div style={{ fontSize: 9.5, color: '#94a3b8', marginTop: 1 }}>
                            {formatBytes(m.size)}
                          </div>
                        ) : null}
                      </div>
                    </div>
                  );
                })}
              </div>
            </>
          )}
        </div>

        {/* Footer */}
        <div
          style={{
            padding: '14px 20px',
            borderTop: '1px solid rgba(255, 255, 255, 0.08)',
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'center',
            background: '#120f20',
            flexWrap: 'wrap',
            gap: 12,
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, minWidth: 0, flex: 1 }}>
            {selected ? (
              <>
                <img
                  src={selected}
                  alt=""
                  style={{ width: 36, height: 36, borderRadius: 6, objectFit: 'cover', border: '1px solid rgba(255,255,255,0.2)' }}
                />
                <div style={{ minWidth: 0, overflow: 'hidden' }}>
                  <div style={{ fontSize: 11, color: '#94a3b8' }}>{adminTranslate("Selected Image:")}</div>
                  <div style={{ fontSize: 12, color: '#34d399', fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                    {selected}
                  </div>
                </div>
              </>
            ) : (
              <span style={{ fontSize: 12, color: '#64748b' }}>No image currently selected</span>
            )}
          </div>

          <div style={{ display: 'flex', gap: 10, alignItems: 'center' }}>
            <button type="button" className="sa-btn ghost" onClick={onClose} style={{ padding: '8px 16px' }}>
              Cancel
            </button>
            <button
              type="button"
              className="sa-btn primary"
              disabled={!selected}
              onClick={() => {
                if (selected) {
                  onSelect(selected);
                  onClose();
                }
              }}
              style={{
                background: selected ? '#10b981' : '#334155',
                borderColor: selected ? '#10b981' : '#334155',
                padding: '8px 20px',
                fontWeight: 700,
                cursor: selected ? 'pointer' : 'not-allowed',
                display: 'inline-flex',
                alignItems: 'center',
                gap: 6,
              }}
            >
              <span>✓</span>
              <span>Choose Photo</span>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

let liveStoreSettings: { storeName?: string; logo?: string } = {};

function updateLiveSettingsCache() {
  try {
    fetch('/api/settings')
      .then((r) => r.json())
      .then((s) => {
        if (s) liveStoreSettings = s;
      })
      .catch(() => {});
    fetch('/api/products')
      .then((r) => r.json())
      .then((ps) => {
        if (Array.isArray(ps) && typeof window !== 'undefined') (window as any).__CATALOG_CACHE = ps;
      })
      .catch(() => {});
  } catch {}
}
updateLiveSettingsCache();

function code128Svg(text: string, height = 28, maxWidth = 220): string {
  const PATTERNS = [
    '212222','222122','222221','121223','121322','131222','122213','122312','132212','221213',
    '221312','231212','112232','122132','122231','113222','123122','123221','223211','221132',
    '221231','213212','223112','312131','311222','321122','321221','312212','322112','322211',
    '212123','212321','232121','111323','131123','131321','112313','132113','132311','211313',
    '231113','231311','112133','112331','132131','113123','113321','133121','313121','211331',
    '231131','213113','213311','213131','311123','311321','331121','312113','312311','332111',
    '314111','221411','431111','111224','111422','121124','121421','141122','141221','112214',
    '112412','122114','122411','142112','142211','241211','221114','413111','241112','134111',
    '111242','121142','121241','114212','124112','124211','411212','421112','421211','212141',
    '214121','412121','111143','111341','131141','114113','114311','411113','411311','113141',
    '114131','311141','411131','211412','211214','211232','2331112'
  ];
  const clean = String(text || '').replace(/[^\x20-\x7E]/g, '');
  if (!clean) return '';
  let sum = 104;
  const codes = [104];
  for (let i = 0; i < clean.length; i++) {
    const code = clean.charCodeAt(i) - 32;
    codes.push(code);
    sum += code * (i + 1);
  }
  codes.push(sum % 103);
  codes.push(106);
  let bars = '';
  for (const c of codes) {
    const pat = PATTERNS[c];
    if (pat) {
      for (let j = 0; j < pat.length; j++) {
        bars += (j % 2 === 0 ? '1' : '0').repeat(parseInt(pat[j]));
      }
    }
  }
  let rects = '';
  for (let i = 0; i < bars.length; i++) {
    if (bars[i] === '1') rects += `<rect x="${i}" y="0" width="1" height="${height}" fill="#000000" />`;
  }
  return `<svg viewBox="0 0 ${bars.length} ${height}" style="height:${height}px; max-width:${maxWidth}px; width:100%; display:block; margin:0 auto;" shape-rendering="crispEdges">${rects}</svg>`;
}

